const updatePesananStatus = `-- name: UpdatePesananStatus :one
UPDATE pesanan
SET status = $1,
    catatan = COALESCE(NULLIF($2::text, ''), catatan)
WHERE id = $3
RETURNING id, nomor_pesanan, status, updated_at
`

type UpdatePesananStatusParams struct {
	Status  string      `json:"status"`
	Catatan string      `json:"catatan"`
	ID      pgtype.UUID `json:"id"`
}

type UpdatePesananStatusRow struct {
	ID           pgtype.UUID        `json:"id"`
	NomorPesanan string             `json:"nomor_pesanan"`
	Status       string             `json:"status"`
	UpdatedAt    pgtype.Timestamptz `json:"updated_at"`
}

func (q *Queries) UpdatePesananStatus(ctx context.Context, arg UpdatePesananStatusParams) (UpdatePesananStatusRow, error) {
	row := q.db.QueryRow(ctx, updatePesananStatus, arg.Status, arg.Catatan, arg.ID)
	var i UpdatePesananStatusRow
	err := row.Scan(
		&i.ID,
		&i.NomorPesanan,
		&i.Status,
		&i.UpdatedAt,
	)
	return i, err
}

const updatePesananStokStatus = `-- name: UpdatePesananStokStatus :exec
UPDATE pesanan
SET stok_status = $1,
    stok_hold_expires_at = $2
WHERE id = $3
`

type UpdatePesananStokStatusParams struct {
	StokStatus        string             `json:"stok_status"`
	StokHoldExpiresAt pgtype.Timestamptz `json:"stok_hold_expires_at"`
	ID                pgtype.UUID        `json:"id"`
}

func (q *Queries) UpdatePesananStokStatus(ctx context.Context, arg UpdatePesananStokStatusParams) error {
	_, err := q.db.Exec(ctx, updatePesananStokStatus, arg.StokStatus, arg.StokHoldExpiresAt, arg.ID)
	return err
}
